    case 0: return false;                       /* f */
    case 1: return un;                          /* un */
    case 2: return !un && a === b;              /* eq */
    case 3: return un || a === b;               /* ueq */
    case 4: return !un && a < b;                /* olt */
    case 5: return un || a < b;                 /* ult */
    case 6: return !un && a <= b;               /* ole */
    case 7: return un || a <= b;                /* ule */
    case 8: return false;                       /* sf */
    case 9: return un;                          /* ngle */
    case 10: return !un && a === b;             /* seq */
    case 11: return un || a === b;              /* ngl */
    case 12: return !un && a < b;               /* lt */
    case 13: return un || a < b;                /* nge */
